-- 019_fix_block_linking_prefix_match.sql
-- 017 linked classes to blocks with exact class_code match, which missed groups where the real
-- imported class_code has a subject suffix appended (e.g. NOVACURR group '11_1' -> actual class_code '11_1/Ma').
-- Re-link using both exact match and 'starts with group/' match, then backfill student_class again.

UPDATE classes SET block_id = (SELECT block_id FROM curriculum_blocks WHERE block_name = 'Other Half sets' AND year_group = 7 AND band = 'a' LIMIT 1) WHERE (class_code = '7a/Oh1' OR class_code LIKE '7a/Oh1/%') AND block_id IS NULL;
UPDATE classes SET block_id = (SELECT block_id FROM curriculum_blocks WHERE block_name = 'Maths sets' AND year_group = 7 AND band = 'a' LIMIT 1) WHERE (class_code = '7a/Ma1' OR class_code LIKE '7a/Ma1/%') AND block_id IS NULL;
