-- Re-backfill student_class.block_id now that more classes are correctly linked
UPDATE student_class sc SET block_id = c.block_id FROM classes c WHERE sc.class_id = c.class_id AND c.block_id IS NOT NULL AND sc.block_id IS NULL;
